#!/usr/bin/env python3
import sys, os, io, csv, json, gzip, re
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def parse_iso(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s).astimezone(UTC)


def to_epoch(dt):
    return int(dt.timestamp()) if dt.tzinfo else None


def local_to_utc(naive, tz, dst_hint=None):
    """dst_hint: True -> DST occurrence, False -> standard, None -> first."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset():
        if dst_hint is None:
            pick = a
        else:
            pick = a if (bool(a.dst()) == dst_hint) else b
            if bool(a.dst()) == bool(b.dst()):
                pick = a
    else:
        pick = a
    return pick.astimezone(UTC)


def std_offset(tz, d):
    dt = datetime(d.year, d.month, d.day, 12, tzinfo=tz)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


def parse_abbr(text, tz):
    out = []
    hdr = None
    for line in lines_of(text):
        row = next(csv.reader([line]))
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            hdr = row
            continue
        if hdr is None:
            continue
        r = dict(zip(hdr, row))
        m = re.match(r'(\d+):(\d+):(\d+)\s*([AaPp][Mm])?$', r['Time'])
        h, mi, s = int(m[1]), int(m[2]), int(m[3])
        if m[4]:
            pm = m[4].upper() == 'PM'
            h = h % 12 + (12 if pm else 0)
        mo, d, y = r['Date'].split('/')
        naive = datetime(int(y), int(mo), int(d), h, mi, s)
        z = r.get('Zone', '').upper()
        hint = True if z.endswith('DT') else False if z.endswith('ST') else None
        out.append((r['Record'], r['Badge'], r['Punch'].upper(), local_to_utc(naive, tz, hint)))
    return out


def parse_epoch(text, tz):
    out = []
    schema = 1
    for line in lines_of(text):
        o = json.loads(line)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ms = o['punch_id'], o['employee'], o['direction'], o['epoch_ms']
            sec = int(ms // 1000)
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            if 'ts_ms' in o:
                sec = int(o['ts_ms'] // 1000)
            else:
                sec = int(o['ts'] // 1)
        out.append((str(pid), emp, d.upper(), datetime.fromtimestamp(sec, UTC)))
    return out


def parse_offset(text, tz):
    out = []
    rows = list(csv.reader(lines_of(text), delimiter=';'))
    hdr = rows[0]
    for row in rows[1:]:
        r = dict(zip(hdr, row))
        d = 'IN' if r['event'].strip() == 'clock_in' else 'OUT'
        out.append((r['punch_id'], r['employee'], d, parse_iso(r['timestamp'])))
    return out


def parse_legacy(text, tz):
    out = []
    off = None
    for line in lines_of(text):
        t = line[0]
        if t == 'H':
            m = re.match(r'([+-])(\d\d)(\d\d)', line[13:18])
            if m:
                v = timedelta(hours=int(m[2]), minutes=int(m[3]))
                off = -v if m[1] == '-' else v
            else:
                off = None
        elif t == 'D':
            pid = line[1:9]
            badge = 'E' + line[9:15].strip()
            d = 'IN' if line[15] == 'I' else 'OUT'
            naive = datetime.strptime(line[16:30], '%Y%m%d%H%M%S')
            o = off if off is not None else std_offset(tz, naive.date())
            out.append((pid, badge, d, (naive - o).replace(tzinfo=UTC)))
    return out


def parse_de(text, tz):
    out = []
    lines = lines_of(text)
    hdr = lines[0].split('\t')
    for line in lines[1:]:
        r = dict(zip(hdr, line.rstrip('\n').split('\t')))
        d = 'IN' if r['Buchung'].strip() == 'K' else 'OUT'
        dd, mm, yy = r['Datum'].strip().split('.')
        hh, mi = r['Uhrzeit'].strip().split(':')[:2]
        naive = datetime(int(yy), int(mm), int(dd), int(hh), int(mi))
        z = r.get('Zeitzone', '').strip().upper()
        hint = True if z == 'MESZ' else False if z == 'MEZ' else None
        out.append((r['Nr'].strip(), r['Ausweis'].strip(), d, local_to_utc(naive, tz, hint)))
    return out


def parse_lcsv(text, tz):
    out = []
    rows = list(csv.reader(lines_of(text)))
    hdr = [c.strip() for c in rows[0]]
    for row in rows[1:]:
        r = dict(zip(hdr, row))
        naive = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'].strip(), r['employee_id'].strip(), r['direction'].strip().upper(),
                    local_to_utc(naive, tz, None)))
    return out


def parse_ljsonl(text, tz):
    out = []
    for line in lines_of(text):
        o = json.loads(line)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], p['type'].upper(), local_to_utc(naive, tz, None)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_lcsv,
           'local-jsonl': parse_ljsonl}


def dec(s):
    return Fraction(s.strip())


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])

    sites = {}
    with open(os.path.join(inp, 'sites.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    with open(os.path.join(inp, 'employees.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), dec(r['hourly_rate'])))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}   # (site,id) -> [emp, dir, instant]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        files = []
        for root, _, fs in os.walk(d):
            for fn in fs:
                files.append(os.path.join(root, fn))
        for p in sorted(files):
            for pid, emp, direc, inst in PARSERS[fmt](read_text(p), tz):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp, direc, inst]

    # 2. corrections
    corr = []
    cd = os.path.join(inp, 'corrections')
    if os.path.isdir(cd):
        for root, _, fs in os.walk(cd):
            for fn in fs:
                with io.StringIO(read_text(os.path.join(root, fn)), newline='') as f:
                    for r in csv.DictReader(f):
                        r = {k: (v or '').strip() for k, v in r.items() if k}
                        corr.append(r)
    corr = [(parse_iso(r['issued_at']), r) for r in corr]
    corr = [(t, r) for t, r in corr if t <= cutoff]
    corr.sort(key=lambda x: (x[0], x[1]['correction_id']))
    applied = 0
    for _, r in corr:
        k = (r['site'], r['punch_id'])
        a = r['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = parse_iso(r['time'])
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [r['employee'], r['type'].upper(), parse_iso(r['time'])]
                applied += 1
    ps = [(e, d, t, k[0], k[1]) for k, (e, d, t) in punches.items() if e in emps]

    # 3. duplicates
    by = {}
    for p in ps:
        by.setdefault(p[0], []).append(p)
    kept = {}
    dropped = []
    for e, lst in by.items():
        lst.sort(key=lambda p: (p[2], 0 if p[1] == 'OUT' else 1, p[3], p[4]))
        last = None
        kl = []
        for p in lst:
            if last is not None and last[1] == p[1] and (p[2] - last[2]).total_seconds() <= 300:
                dropped.append(p)
                continue
            kl.append(p)
            last = p
        kept[e] = kl

    # 4. round
    def rnd(p):
        tz = sites[p[3]][0]
        off = p[2].astimezone(tz).utcoffset()
        loc = int(p[2].timestamp()) + int(off.total_seconds())
        new = (loc + 180) // 360 * 360
        return datetime.fromtimestamp(int(p[2].timestamp()) + new - loc, UTC)

    def workday(e, inst):
        return inst.astimezone(ZoneInfo(sites[emps[e]][0].key)).date()

    def in_period(d):
        return pstart <= d <= pend

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0))
           for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    for p in dropped:
        if in_period(workday(p[0], rnd(p))):
            exc['duplicates_dropped'] += 1

    for e, lst in kept.items():
        rl = [(p, rnd(p)) for p in lst]
        shifts = []
        i = 0
        n = len(rl)
        pending = None
        for p, r in rl:
            if p[1] == 'IN':
                if pending is not None:
                    if in_period(workday(e, pending[1])):
                        exc['open_shifts'] += 1
                pending = (p, r)
            else:
                if pending is not None and (r - pending[1]).total_seconds() <= 16 * 3600:
                    shifts.append((pending, (p, r)))
                    pending = None
                else:
                    if pending is not None:
                        if in_period(workday(e, pending[1])):
                            exc['open_shifts'] += 1
                        pending = None
                    if in_period(workday(e, r)):
                        exc['orphan_outs'] += 1
        if pending is not None and in_period(workday(e, pending[1])):
            exc['open_shifts'] += 1

        sh = []
        for (ip, ir), (op, orr) in shifts:
            wd = workday(e, ir)
            if not in_period(wd):
                continue
            worked = max(0, int((orr - ir).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            tz = sites[ip[3]][0]
            night = 0
            t = ir
            while t < orr:
                h = t.astimezone(tz).hour
                if h >= 22 or h < 6:
                    night += 1
                t += timedelta(minutes=1)
            night = min(night, paid)
            sh.append([ir, wd, paid, night])
        sh.sort(key=lambda s: s[0])
        daily = {}
        weekly = {}
        for ir, wd, paid, night in sh:
            used = daily.get(wd, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[wd] = used + paid
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wu = weekly.get(wk, 0)
            wot = max(0, wu + nd - 2400) - max(0, wu - 2400)
            weekly[wk] = wu + nd
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt in rates.get(e, []):
                if ef <= wd:
                    rate = rt
            rate = rate or Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r = res[e]
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
            r['gross'] += pay

    def money(fr):
        c = (fr * 100 + Fraction(1, 2)).__floor__()
        return f"{c // 100}.{c % 100:02d}"

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totg = 0
    out_e = {}
    for e in sorted(res):
        r = res[e]
        g = (r['gross'] * 100 + Fraction(1, 2)).__floor__()
        totg += g
        for k in tot:
            tot[k] += r[k]
        out_e[e] = dict(shifts=r['shifts'], paid_minutes=r['paid_minutes'],
                        overtime_minutes=r['overtime_minutes'], night_minutes=r['night_minutes'],
                        gross=f"{g // 100}.{g % 100:02d}")
    tot['gross'] = f"{totg // 100}.{totg % 100:02d}"
    with open(outp, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=out_e,
                       exceptions=exc, totals=tot), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
